                ConversionSentence(40, "Spread knowledge, hope, compassion, and uplifting messages.", "علم، امید، ہمدردی اور اچھے پیغامات کو فروغ دیں۔", "Ilm, umeed aur achay paighamaat ko farogh dein."),
                ConversionSentence(41, "Online communities provide great support for shared hobbies.", "آن لائن فورمز مشترکہ مشاغل کے لیے بہترین مددگار ہیں۔", "Online communities shauq poora karne ke liye achi hain."),
                ConversionSentence(42, "Learn how to identify deepfakes and manipulated digital media.", "جعلی ویڈیوز اور جھوٹی تصاویر کو پہچاننا سیکھیں۔", "Jaali videos aur jhooti tasaveer ko pehchanna seekhein."),
                ConversionSentence(43, "Critical thinking is the ultimate shield against online falsehood.", "غور و فکر کرنا آن لائن جھوٹ کے خلاف سب سے بڑی ڈھال ہے۔", "Ghaur-o-fikr karna online jhoot ke khilaf sab se barri dhaal hai."),
