                ConversionSentence(4, "Children eagerly wait to receive their Eid gifts and Eidi pocket money.", "بچے عیدی اور تحائف حاصل کرنے کا بے صبری سے انتظار کرتے ہیں۔", "Bachay eidi aur tahaif haasil karne ka intezar kartay hain."),
                ConversionSentence(5, "Wishing you a blissful wedding anniversary full of enduring love.", "آپ کو شادی کی سالگرہ پر دلی مبارکباد اور ڈھیروں دعائیں۔", "Aap ko shadi ki salgirah par dili mubarakbaad aur duaein."),
                ConversionSentence(6, "The colorful mehndi ceremony was filled with traditional songs and dances.", "مہندی کی تقریب روایتی گیتوں اور خوشیوں سے سجی ہوئی تھی۔", "Mehndi ki taqreeb riwayati geeton aur khushiyon se saji thi."),
                ConversionSentence(7, "Happy birthday! May your upcoming year be filled with success.", "سالگرہ مبارک! دعا ہے کہ آپ کا اگلا سال کامیابیوں سے بھرپور ہو۔", "Salgirah mubarak! Dua hai ke agla saal kamyabiyon se bharpoor ho."),
                ConversionSentence(8, "We exchanged delicious festive sweets and savory snacks with neighbors.", "ہم نے پڑوسیوں کے ساتھ مٹھائیاں اور لذیذ کھانے شیئر کیے۔", "Hum ne parosiyon ke sath mithaiyan aur khanay share kiye."),
                ConversionSentence(9, "The whole bazaar is brightly illuminated with colorful fairy lights.", "پورا بازار رنگ برنگی برقی قمقموں کی روشنیوں سے جگمگا رہا ہے۔", "Poora bazaar rang barangi lighton se jagmaga raha hai."),
                ConversionSentence(10, "Festivals provide a joyful opportunity to mend ties and forgive.", "تہوار دلوں کی دوریاں مٹانے اور ایک دوسرے کو معاف کرنے کا موقع ہیں۔", "Tehwaar dilon ki dooriyan mitanay aur maaf karne ka mauqa hain."),
                ConversionSentence(11, "What are your family's special plans for the long Eid holiday?", "عید کی لمبی چھٹیوں پر آپ کے خاندان کا کیا خاص پروگرام ہے؟", "Eid ki chuttiyon par aap ke khandan ka kya khaas program hai?"),
                ConversionSentence(12, "We performed the Eid congregational prayer at the grand mosque.", "ہم نے جامع مسجد میں عید کی باجماعت نماز ادا کی۔", "Hum ne jamia masjid mein Eid ki namaz ada ki."),
                ConversionSentence(13, "Wishing our Christian brothers and sisters a very peaceful Christmas.", "ہمارے مسیحی بھائیوں اور بہنوں کو کرسمس کی خوشیاں مبارک ہوں۔", "Hamare Maseehi bhaiyon aur behnon ko Christmas mubarak ho."),
                ConversionSentence(14, "May the arrival of the Islamic New Year bring unity and prosperity.", "نیا اسلامی سال پوری امت کے لیے اتحاد اور خوشحالی لائے۔", "Naya Islami saal ittehad aur khush-haali laye."),
                ConversionSentence(15, "The wedding reception hall was decorated with fragrant white jasmine flowers.", "شادی کا ہال چنبیلی کے تازہ پھولوں کی خوشبو سے مہک رہا تھا۔", "Shadi ka hall chambeli ke taaza phoolon se mehak raha tha."),
                ConversionSentence(16, "We baked a delicious double chocolate birthday cake for the party.", "ہم نے پارٹی کے لیے لذیذ چاکلیٹ کیک بیک کیا۔", "Hum ne party ke liye lazeez chocolate cake bake kiya."),
                ConversionSentence(17, "Everyone embraced each other warmly with genuine smiles and affection.", "سب نے مسکراتے چہروں کے ساتھ ایک دوسرے کو گلے لگایا۔", "Sab ne muskuratay chehron ke sath aik doosray ko galay lagaya."),
                ConversionSentence(18, "May your table be blessed with sumptuous feast and cherished guests.", "اللہ آپ کے دسترخوان کو لذیذ کھانوں اور پیاروں سے سجائے رکھے۔", "Allah aap ke dastarkhwan ko lazeez khanon se sajaye rakhay."),
                ConversionSentence(19, "The young cousins played fun parlor games until late into the night.", "تمام کزنز نے رات گئے تک دلچسپ کھیل کھیلے اور ہنسی مذاق کیا۔", "Tamam cousins ne raat gaye tak dilchasp khel khailay."),
                ConversionSentence(20, "True joy multiplies when shared with those less privileged around us.", "اصل خوشی ضرورت مندوں اور غریبوں کو شامل کرنے سے دوبالا ہوتی ہے۔", "Asal khushi zaroorat-mandon ko shamil karne se barhti hai."),
                ConversionSentence(21, "We distributed food rations and warm clothes to needy families.", "ہم نے مستحق خاندانوں میں راشن اور گرم کپڑے تقسیم کیے۔", "Hum ne mustahiq khandanun mein rashan aur kapray baantay."),
                ConversionSentence(22, "The Independence Day fireworks lit up the midnight sky in emerald green.", "یوم آزادی پر آتش بازی نے رات کے آسمان کو سبز رنگ میں رنگ دیا۔", "Youm-e-Azadi par aatish-baazi ne aasmaan ko chamka diya."),
                ConversionSentence(23, "Singing the national anthem fills every Pakistani heart with pride.", "قومی ترانہ سنتے ہی ہر پاکستانی کا سر فخر سے بلند ہو جاتا ہے۔", "Qaumi tarana suntay hi har Pakistani ka dil fakhr se bhar jata hai."),
                ConversionSentence(24, "May peace, harmony, and progress shine over our beloved nation.", "اللہ ہمارے پیارے وطن کو ہمیشہ امن، ترقی اور خوشحالی عطا کرے۔", "Allah hamare watan ko hamesha aman aur taraqi ata karay."),
                ConversionSentence(25, "The family gathered for a delicious Iftar feast at sunset.", "غروبِ آفتاب پر پورا خاندان لذیذ افطاری کے لیے اکٹھا ہوا۔", "Ghuroob-e-aaftaab par poora khandan iftari ke liye ikattha hua."),
                ConversionSentence(26, "Crispy vegetable pakoras and fruit chaat are staples of Iftar.", "پکوڑے اور فروٹ چاٹ ہمارے روایتی دسترخوان کی جان ہیں۔", "Pakorray aur fruit chaat hamari iftari ki jaan hain."),
                ConversionSentence(27, "Lighting traditional earthen diyas brings warmth to autumn evenings.", "مٹی کے روایتی دیئے جلانا شام کو ایک خوبصورت روپ دیتا ہے۔", "Mitti ke deeyay jalana shaam ko khubsurat roop deta hai."),
                ConversionSentence(28, "Hearty congratulations on the birth of your newborn baby boy!", "اللہ نے آپ کو چاند سا بیٹا عطا کیا ہے، بہت بہت مبارک ہو!", "Allah ne aap ko beta ata kiya hai, bohat mubarak ho!"),
                ConversionSentence(29, "May the newborn baby grow up in radiant health, faith, and wisdom.", "اللہ بچے کو لمبی عمر، بہترین صحت اور روشن نصیب عطا کرے۔", "Allah bachay ko lambi umar aur roshan naseeb ata karay."),
                ConversionSentence(30, "Gathering around our grandparents for traditional stories is priceless.", "دادا دادی کے گرد بیٹھ کر کہانیاں سننا انمول وقت ہوتا ہے۔", "Dada dadi ke gird baith kar kahaniyan sunna anmol hai."),
                ConversionSentence(31, "We sent lovely customized gift hampers to our corporate clients.", "ہم نے اپنے کلائنٹس کو خوبصورت تحائف کے ٹوکرے بھیجے۔", "Hum ne apne clients ko khubsurat tahaif ke baskets bhejay."),
                ConversionSentence(32, "The groom looked regal in his hand-tailored off-white Sherwani.", "دولہا اپنے کڑھائی والے سفید لباس میں بہت باوقار لگ رہا تھا۔", "Dulha apne safaid libaas mein bohat ba-waqaar lag raha tha."),
                ConversionSentence(33, "The bride's intricate henna tattoo designs were breathtakingly delicate.", "دلہن کے ہاتھوں پر لگی باریک مہندی کے ڈیزائن لاجواب تھے۔", "Dulhan ke haathon par lagi mehndi ke design la-jawab thay."),
                ConversionSentence(34, "May your new matrimonial journey be blessed with endless mutual trust.", "اللہ آپ دونوں کے نئے ازدواجی سفر کو محبت اور اعتماد سے بھر دے۔", "Allah aap dono ke azdawaji safar ko mohabbat se bhar de."),
                ConversionSentence(35, "We held a spiritual Milad gathering with devotional poetry recitations.", "ہم نے گھر میں بابرکت محفلِ میلاد اور نعت خوانی سجائی۔", "Hum ne ghar mein ba-barkat Mehfil-e-Milad sajayi."),
                ConversionSentence(36, "May divine blessings illuminate your heart with tranquility.", "اللہ تعالیٰ کا کرم اور سکون آپ کے دل کو منور رکھے۔", "Allah Ta'ala ka karam aur sukoon aap ke dil ko munawwar rakhay."),
                ConversionSentence(37, "The children put on a colorful drama performance at the school annual day.", "بچوں نے اسکول کے سالانہ فنکشن پر رنگارنگ ٹیبلو پیش کیا۔", "Bachon ne school ke annual function par tableaus pesh kiye."),
                ConversionSentence(38, "Parents applauded proudly as their kids received achievement awards.", "بچوں کے انعامات جیتنے پر والدین نے فخر سے تالیاں بجائیں۔", "Bachon ke inaam jeetnay par walidain ne taaliyan bajayein."),
                ConversionSentence(39, "Celebrating cultural heritage keeps our rich traditions alive.", "اپنی تہذیب اور روایات کا جشن منانا ورثے کو زندہ رکھتا ہے۔", "Apni tehzeeb ka jashan manana virsay ko zinda rakhta hai."),
                ConversionSentence(40, "May the light of joy dispel all shadows of grief from your home.", "اللہ کرے خوشیوں کا اجالا آپ کے گھر سے ہر غم کو دور کر دے۔", "Allah karay khushiyon ka ujala har gham ko door kar de."),
                ConversionSentence(41, "We toasted with fresh pomegranate and peach sparkling juice.", "ہم نے انار اور آڑو کے تازہ شربت سے تقریب کا آغاز کیا۔", "Hum ne anaar aur aarroo ke taaza sharbat se aaghaz kiya."),
                ConversionSentence(42, "The family reunion brought together relatives from three continents.", "خاندانی ملن نے تین مختلف براعظموں سے رشتہ داروں کو جوڑ دیا۔", "Khandani milan ne mukhtalif mulkon se rishtedaron ko jorr diya."),
                ConversionSentence(43, "Old photo albums opened a floodgate of joyful nostalgic memories.", "پرانی تصاویر نے ماضی کی خوبصورت اور حسین یادیں تازہ کر دیں۔", "Purani tasaveer ne maazi ki haseen yaadein taaza kar dein."),
                ConversionSentence(44, "Laughter of happy children is the sweetest music in the universe.", "بچوں کے قہقہے اور مسکراہٹیں دنیا کا سب سے پیارا نغمہ ہیں۔", "Bachon ke qehqahay dunya ka sab se pyara naghma hain."),
                ConversionSentence(45, "Cherish every fleeting milestone with presence, humility, and gratitude.", "ہر خوشی کے موقع پر عاجزی اور شکر گزاری کے ساتھ حاضر رہیں۔", "Har khushi ke mauqa par aajzi aur shukr ke sath rahein."),
                ConversionSentence(46, "We tied green and white balloons across the entrance porch.", "ہم نے داخلی دروازے پر سبز اور سفید غبارے سجائے۔", "Hum ne entrance par sabz aur safaid ghubaray sajaye."),
                ConversionSentence(47, "May your homes always resonate with heartfelt congratulations!", "اللہ کرے آپ کا گھر ہمیشہ مبارکبادوں اور خوشیوں سے گونجتا رہے!", "Allah karay aap ka ghar hamesha mubarakbaadon se goonjay!"),
                ConversionSentence(48, "Sending you warm wishes for a prosperous and jubilant holiday season!", "آپ کے لیے چھٹیوں کے پرمسرت موسم پر نیک تمناؤں کا تحفہ!", "Aap ke liye chuttiyon par naik tamannaon ka tohfa!"),
                ConversionSentence(49, "Festive occasions remind us of what matters most: love and family.", "تہوار ہمیں یاد دلاتے ہیں کہ اصل دولت محبت اور خاندان ہے۔", "Tehwaar yaad dilatay hain ke asal daulat mohabbat aur khandan hai."),
                ConversionSentence(50, "May all your celebrations be crowned with peace, barakah, and bliss!", "اللہ تعالیٰ آپ کی تمام خوشیوں میں برکت، امن اور مسرتیں عطا فرمائے!", "Allah Ta'ala aap ki tamam khushiyon mein barkat ata farmaye!")
            )),
            // 38. Relationships & Family (50 Sentences)
            ConversionTopic(38, "Relationships & Family", "رشتے اور خاندان", "groups", "Parents, siblings, marriage, respect, parenting, and bonds.", listOf(
                ConversionSentence(1, "Honoring and caring for aging parents is the highest moral virtue.", "بوڑھے والدین کی خدمت اور ادب سب سے بڑی نیکی ہے۔", "Boorhay walidain ki khidmat aur adab sab se barri naiki hai."),
                ConversionSentence(2, "A warm, supportive family is a person's safest refuge in storms.", "ایک پیار کرنے والا خاندان زندگی کے طوفانوں میں سب سے محفوظ پناہ گاہ ہے۔", "Aik pyar karne wala khandan sab se mahfooz panah-gah hai."),
                ConversionSentence(3, "Open, honest communication builds unbreakable trust between siblings.", "کھلی اور سچی بات چیت بہن بھائیوں میں اٹوٹ اعتماد پیدا کرتی ہے۔", "Khuli aur sachi baat cheet behan bhaiyon mein aitemad banati hai."),
                ConversionSentence(4, "Patience and empathy are the pillars of a peaceful marriage.", "صبر اور باہمی احساس ایک پرسکون ازدواجی زندگی کے ستون ہیں۔", "Sabr aur baahmi ehsas pursukoon shadi shuda zindagi ke sutoon hain."),
                ConversionSentence(5, "Spend quality screen-free time talking with your growing children daily.", "اپنے بڑھتے ہوئے بچوں کے ساتھ روزانہ بغیر موبائل کے وقت گزاریں۔", "Apne bachon ke sath rozana mobile ke baghair waqt guzarein."),
                ConversionSentence(6, "Grandparents pass down timeless wisdom, resilience, and heritage.", "دادا دادی بچوں کو حکمت، اخلاق اور خاندانی ورثہ سکھاتے ہیں۔", "Dada dadi bachon ko hikmat aur saqafat sikhatay hain."),
                ConversionSentence(7, "Always forgive family misunderstandings with a generous heart.", "خاندانی غلط فہمیوں کو ہمیشہ بڑے دل کے ساتھ معاف کر دیا کریں۔", "Khandani ghalt-fehmiyon ko hamesha baray dil se maaf karein."),
                ConversionSentence(8, "Express gratitude to your spouse for the little unseen efforts they make.", "اپنے جیون ساتھی کی چھوٹی چھوٹی کوششوں پر ان کا شکریہ ادا کریں۔", "Apne jeevan saathi ki koshishon par un ka shukriya ada karein."),
                ConversionSentence(9, "Childhood memories shared with brothers and sisters stay forever.", "بہن بھائیوں کے ساتھ گزرا بچپن زندگی بھر دل میں زندہ رہتا ہے۔", "Behan bhaiyon ke sath guzra bachpan hamesha yaad rehta hai."),
                ConversionSentence(10, "Love is not merely an emotion; it is an everyday conscious commitment.", "محبت صرف ایک جذبہ نہیں بلکہ روزانہ نبھایا جانے والا وعدہ ہے۔", "Mohabbat sirf aik jazba nahi balkay rozana ka wada hai."),
                ConversionSentence(11, "How do you maintain balance between demanding career and family time?", "آپ اپنے مصروف کیریئر اور خاندانی وقت میں کیسے توازن رکھتے ہیں؟", "Aap career aur family waqt mein kaisay tawazun rakhtay hain?"),
                ConversionSentence(12, "Establish regular family dinners where everyone shares their day.", "روزانہ رات کا کھانا سب اکٹھے کھائیں اور دن کے حالات بتائیں۔", "Rozana raat ka khana sab ikatthay khayein aur baat karein."),
                ConversionSentence(13, "Listen to your teenager without immediately judging or scolding.", "اپنے نوجوان بچوں کی بات بغیر تنقید کیے پہلے غور سے سنیں۔", "Apne naujawan bachon ki baat baghair tanqeed suniye."),
                ConversionSentence(14, "True friendship is a rare treasure nurtured across decades.", "سچی دوستی ایک نایاب موتی ہے جو برسوں کی مخلصانہ وفا سے بنتا ہے۔", "Sachi dosti aik nayaab moti hai jo saalon mein banti hai."),
                ConversionSentence(15, "Support your partner's personal dreams and intellectual pursuits.", "اپنے جیون ساتھی کے خوابوں اور مقاصد کی ہمیشہ حوصلہ افزائی کریں۔", "Apne partner ke khwabon aur maqasid ki himayat karein."),
                ConversionSentence(16, "Never raise your voice in anger when speaking to your mother.", "اپنی والدہ کے سامنے غصے میں آواز کبھی اونچی مت کریں۔", "Apni walida ke samnay ghussay mein aawaz oonchi mat karein."),
                ConversionSentence(17, "A father's quiet sacrifices are the foundation of children's success.", "باپ کی خاموش قربانیاں ہی بچوں کی کامیابی کی بنیاد ہوتی ہیں۔", "Baap ki khamosh qurbaniyan bachon ki bunyad hoti hain."),
                ConversionSentence(18, "Teach boys and girls emotional resilience and mutual respect.", "بیٹوں اور بیٹیوں کو باہمی عزت، برداشت اور خودداری سکھائیں۔", "Beton aur betiyon ko izzat, bardasht aur saleeqa sikhayein."),
                ConversionSentence(19, "Celebrate each other's triumphs as if they were your own.", "اپنوں کی کامیابیوں پر ایسے خوش ہوں جیسے وہ آپ کی اپنی ہوں۔", "Apnon ki kamyabi par dil se khush hon."),
                ConversionSentence(20, "A peaceful home is built on mutual respect and shared responsibilities.", "ایک پرسکون گھر باہمی احترام اور کام بانٹنے سے بنتا ہے۔", "Aik pursukoon ghar baahmi ihtiram se banta hai."),
                ConversionSentence(21, "Help your siblings when they stumble without boasting about it.", "جب بہن بھائی مشکل میں ہوں تو بغیر احسان جتائے مدد کریں۔", "Jab behan bhai mushkil mein hon to baghair ahsan madad karein."),
                ConversionSentence(22, "A mother's prayers can move mountains and alter destinies.", "ماں کی دعائیں تقدیر بدلنے کی طاقت رکھتی ہیں۔", "Maa ki duaein taqdeer badalnay ki taaqat rakhti hain."),
                ConversionSentence(23, "Take your family on peaceful weekend nature walks and outings.", "ویک اینڈ پر خاندان کے ساتھ قدرتی اور پرسکون مقامات پر جائیں۔", "Weekend par family ke sath pursukoon jaghon par jayein."),
                ConversionSentence(24, "Do not let petty financial disputes poison sacred family bonds.", "چھوٹے مالی جھگڑوں کو مقدس خاندانی رشتوں پر حاوی مت ہونے دیں۔", "Chhotay maali jhagron ko rishton par haawi mat honay dein."),
                ConversionSentence(25, "Teach youngsters the beauty of greeting elders with adab and salam.", "نوجوانوں کو بزرگوں کو ادب سے سلام کرنے کا سلیقہ سکھائیں۔", "Naujawanon ko bazurgon ko adab se salam karna sikhayein."),
                ConversionSentence(26, "Kind words within home walls cost nothing but create priceless peace.", "گھر کے اندر کہے گئے میٹھے بول انمول سکون لاتے ہیں۔", "Ghar ke andar bolay gaye meethay bol sukoon laatay hain."),
                ConversionSentence(27, "Cherish the moments you have today with loved ones unconditionally.", "اپنے پیاروں کے ساتھ موجود آج کے ہر لمحے کی دل سے قدر کریں۔", "Apne pyaron ke sath maujood har lamhay ki qadr karein."),
                ConversionSentence(28, "Reaching out to an estranged relative brings profound blessings.", "ناراض رشتہ دار کو منا لینا زندگی میں بے پناہ برکت لاتا ہے۔", "Naraaz rishtedaar ko mana lena barkat laata hai."),
                ConversionSentence(29, "A solid marriage is two imperfect souls refusing to give up on each other.", "کامیاب شادی دو انسانوں کا ایک دوسرے کا ساتھ نبھانے کا عزم ہے۔", "Kamyab shadi aik doosray ka sath nibhanay ka azm hai."),
                ConversionSentence(30, "Children learn far more from what parents do than what they preach.", "بچے والدین کی نصیحتوں سے زیادہ ان کے عمل سے سیکھتے ہیں۔", "Bachay walidain ke amal se zyada seekhtay hain."),
                ConversionSentence(31, "Encourage your children to pursue education with curiosity and joy.", "بچوں کو شوق اور خوشی کے ساتھ علم حاصل کرنے کی ترغیب دیں۔", "Bachon ko shauq ke sath ilm haasil karne ki targheeb dein."),
                ConversionSentence(32, "Express your love verbally; do not leave it unspoken and hidden.", "اپنی محبت کا اظہار الفاظ سے کریں، اسے دل میں چھپا کر نہ رکھیں۔", "Apni mohabbat ka izhaar alfaaz se karein, chhupa kar na rakhein."),
                ConversionSentence(33, "A warm hug and listening ear can heal a child's broken day.", "پیار سے گلے لگانا اور بات سننا بچے کا دکھ دور کر دیتا ہے۔", "Pyar se galay lagana bachay ka dukh door kar deta hai."),
                ConversionSentence(34, "Respect your spouse's privacy and individual personal space.", "اپنے ساتھی کی ذاتی زندگی اور اسپیس کا ہمیشہ احترام کریں۔", "Apne saathi ki zaati zindagi ka ihtiram karein."),
                ConversionSentence(35, "Family traditions create a comforting sense of shared identity.", "خاندانی روایات بچوں میں تحفظ اور تعلق کا احساس پیدا کرتی ہیں۔", "Khandani riwayaat bachon mein tahaffuz ka ehsas banati hain."),
                ConversionSentence(36, "Keep toxic external gossip far away from your family discussions.", "باہر کی منفی باتوں اور غیبت کو اپنے گھر سے دور رکھیں۔", "Bahar ki manfi baton aur gheebat ko ghar se door rakhein."),
                ConversionSentence(37, "Be the first to apologize when an argument escalates at home.", "جب گھر میں تکرار بڑھے تو معافی مانگنے میں پہل کریں۔", "Jab ghar mein takraar barhay to maafi maangnay mein pehal karein."),
                ConversionSentence(38, "True nobility lies in treating your own family with utmost gentleness.", "سب سے بہترین انسان وہ ہے جو اپنے اہل و عیال کے لیے بہترین ہو۔", "Behtareen insaan woh hai jo apne ahal-e-khana ke liye behtareen ho."),
                ConversionSentence(39, "Remember to call relatives living far away in distant cities.", "دور دراز شہروں میں مقیم رشتہ داروں کو فون کر کے خیریت پوچھیں۔", "Door shehron mein muqeem rishtedaron ki khairiyat poochein."),
                ConversionSentence(40, "A united family can weather any economic storm together.", "ایک متحد خاندان ہر قسم کی معاشی تنگی کا مقابلہ کر سکتا ہے۔", "Aik muttahid khandan har mushkil ka muqabla kar sakta hai."),
                ConversionSentence(41, "Create daily tech-free dinner routines to foster eye contact.", "کھانے کے وقت موبائل دور رکھ کر ایک دوسرے سے بات کریں۔", "Khanay ke waqt mobile door rakh kar baat karein."),
                ConversionSentence(42, "Praise your children's moral character more than their grades.", "بچوں کے نمبرز سے زیادہ ان کے اچھے اخلاق اور کردار کی تعریف کریں۔", "Bachon ke achay ikhlaaq aur kirdaar ki tareef karein."),
                ConversionSentence(43, "A peaceful household is the greatest earthly treasure one can possess.", "ایک پرسکون گھر دنیا کی سب سے بڑی دولت اور نعمت ہے۔", "Aik pursukoon ghar dunya ki sab se barri nemat hai."),
                ConversionSentence(44, "Forgiveness is the glue that mends broken relationships over time.", "معاف کرنا وہ مرہم ہے جو ٹوٹے ہوئے رشتوں کو جوڑ دیتا ہے۔", "Maaf karna woh marham hai jo rishton ko jorr deta hai."),
                ConversionSentence(45, "Value elderly family members and consult them on major life decisions.", "بزرگوں کی قدر کریں اور اہم فیصلوں میں ان سے مشورہ لیں۔", "Bazurgon ki qadr karein aur ahem faislon mein mashwara lein."),
                ConversionSentence(46, "The bond between a brother and sister is filled with playful care.", "بہن بھائی کا رشتہ شرارتوں اور سچی فکر کا خوبصورت سنگم ہے۔", "Behan bhai ka rishta shararton aur fikr ka sangam hai."),
                ConversionSentence(47, "Never compare one child unfavorably against another sibling.", "ایک بچے کا دوسرے سے منفی موازنہ کبھی مت کریں۔", "Aik bachay ka doosray se manfi mawazna mat karein."),
                ConversionSentence(48, "Love, laughter, and prayer are the true foundation of a blessed home.", "محبت، خوشی اور دعائیں ہی برکت والے گھر کی اصل بنیاد ہیں۔", "Mohabbat, khushi aur duaein hi ba-barkat ghar ki bunyad hain."),
                ConversionSentence(49, "Cherish every single day with the people you love most dearly.", "جن سے آپ محبت کرتے ہیں ان کے ساتھ ہر دن کو غنیمت جانیں۔", "Jin se aap mohabbat kartay hain un ke sath har din ki qadr karein."),
                ConversionSentence(50, "May your family be forever guarded by mutual affection and peace!", "اللہ تعالیٰ آپ کے خاندان کو باہمی الفت اور دائمی امن عطا فرمائے!", "Allah Ta'ala aap ke khandan ko hamesha pursukoon rakhay!")
