                ConversionSentence(20, "Work-life balance prevents burnout and sustains long-term passion.", "کام اور زندگی میں توازن تھکن سے بچاتا ہے اور کارکردگی بڑھاتا ہے۔", "Kaam aur zindagi mein tawazun thakan se bachata hai."),
                ConversionSentence(21, "Prepare the meeting agenda in advance and distribute it to attendees.", "میٹنگ کا ایجنڈا پہلے سے تیار کر کے تمام شرکاء کو بھیجیں۔", "Meeting ka agenda pehle se tayar kar ke sab ko bhejein."),
                ConversionSentence(22, "Keep virtual zoom calls focused, structured, and strictly on time.", "آن لائن ویڈیو میٹنگز کو منظم، بامقصد اور وقت پر ختم کریں۔", "Online video meetings ko munazzam aur waqt par khatam karein."),
                ConversionSentence(23, "Document key decisions and share meeting minutes within twenty-four hours.", "میٹنگ کے اہم فیصلوں اور نوٹس کو چوبیس گھنٹے میں شیئر کریں۔", "Meeting ke ahem faislon ke notes 24 ghantay mein bhejein."),
                ConversionSentence(24, "Address conflicts directly, calmly, and privately with empathy.", "اختلافات کو پرسکون انداز میں اور تنہائی میں بات کر کے سلجھائیں۔", "Ikhtilaafaat ko pursukoon andaaz mein akele mein hal karein."),
                ConversionSentence(25, "Mentoring junior colleagues strengthens the collective team capability.", "نئے عملے کی رہنمائی کرنا پوری ٹیم کی طاقت کو بڑھاتا ہے۔", "Naye amlay ki rehnumai karna poori team ko mazboot karta hai."),
